{
  "$schema": "https://json.schemastore.org/package.json",
  "name": "@renai-labs/ren-tui-plugin",
  "version": "0.0.3",
  "description": "Ren TUI plugin for opencode — attribution, command lockdown, and in-TUI Ren navigation. Active only inside a Ren attach.",
  "license": "MIT",
  "author": "Ren Labs, Inc.",
  "homepage": "https://github.com/renai-labs/cli#readme",
  "repository": {
    "type": "git",
    "url": "git+https://github.com/renai-labs/cli.git"
  },
  "bugs": {
    "url": "https://github.com/renai-labs/cli/issues"
  },
  "keywords": [
    "ren",
    "renai",
    "opencode",
    "opencode-plugin",
    "tui",
    "agent",
    "agent-infrastructure"
  ],
  "type": "module",
  "sideEffects": false,
  "publishConfig": {
    "access": "public"
  },
  "exports": {
    ".": {
      "import": "./dist/index.js"
    },
    "./tui": "./dist/index.js"
  },
  "main": "./dist/index.js",
  "files": [
    "dist",
    "README.md",
    "LICENSE"
  ],
  "engines": {
    "node": ">=18"
  },
  "scripts": {
    "build": "bun run scripts/build.ts",
    "sync-opencode-version": "bun run scripts/sync-opencode-version.ts",
    "test": "bun test",
    "typecheck": "tsc --noEmit",
    "prepublishOnly": "bun run scripts/sync-opencode-version.ts --check && bun run build"
  },
  "dependencies": {},
  "devDependencies": {
    "@ren/client-core": "workspace:*",
    "@opencode-ai/plugin": "1.17.9",
    "@opentui/core": "0.3.4",
    "@opentui/solid": "0.3.4",
    "@tsconfig/bun": "catalog:",
    "@types/bun": "catalog:",
    "solid-js": "1.9.10",
    "typescript": "catalog:"
  }
}
